return [
  {
    json: {
      requirement:
        $input.first().json.requirement ||
        "Build an AI Invoice Approval Workflow"
    }
  }
];

return [
  {
    json: {
      requirement: $json.requirement,

      payload: {
        model: "models/gemini-embedding-001",

        content: {
          parts: [
            {
              text: $json.requirement
            }
          ]
        }
      }
    }
  }
];

const vector = $json.embedding?.values;

if (!vector || !Array.isArray(vector)) {
	throw new Error("Embedding vector not found.");
}

const requirement = $("Code (Build Gemini Embedding Payload)")
	.first()
	.json.requirement;

return [
	{
		json: {
			requirement,
			vector,
			vector_dimension: vector.length
		}
	}
];

// Validate Qdrant response
if (
	!$json.result ||
	!Array.isArray($json.result) ||
	$json.result.length === 0
) {
	throw new Error("No workflows found in Qdrant.");
}

// Qdrant returns chunks: collapse to one row per workflow and borrow market data from any chunk that has it
const _all = $json.result || [];
const _market = {};
for (const r of _all) { const p = r.payload || {}; if (p.workflow_name && p.project_rate != null && !_market[p.workflow_name]) _market[p.workflow_name] = p; }
const _seen = new Set();
const _unique = _all.filter(r => { const n = (r.payload || {}).workflow_name || (r.payload || {}).project_name; if (!n || _seen.has(n)) return false; _seen.add(n); return true; })
  .map(r => ({ ...r, payload: { ..._market[(r.payload || {}).workflow_name], ...(r.payload || {}) , ...Object.fromEntries(Object.entries(_market[(r.payload || {}).workflow_name] || {}).filter(([k]) => ["project_rate","business_value","difficulty","estimated_hours","automation_level","market_reason","workflow_description","technologies","integrations","use_cases"].includes(k))) } }));

// Get requirement from previous node
const requirement = $("Code (Extract Embedding)1").first().json.requirement;

// Build Top 5 Workflows
const workflows = _unique.slice(0, 5).map((item, index) => {

	const payload = item.payload || {};

	return {

		rank: index + 1,

		workflow_name: payload.workflow_name || "",

		search_score: Number(item.score || 0),

		project_rate: payload.project_rate || 0,

		business_value: payload.business_value || 0,

		difficulty: payload.difficulty || "",

		estimated_hours: payload.estimated_hours || 0,

		automation_level: payload.automation_level || "",

		market_reason: payload.market_reason || "",

		workflow_description: payload.workflow_description || "",

		workflow_category: payload.workflow_category || "",

		technologies: payload.technologies || "",

		integrations: payload.integrations || "",

		use_cases: payload.use_cases || ""

	};

});

// Highest Search Score
const bestSearchScore =
	workflows.length > 0
		? workflows[0].search_score
		: 0;

// Search Status
const searchStatus =
	bestSearchScore >= 0.65
		? "High Confidence Match"
		: "Low Confidence Match";

// Final Output
return [
	{
		json: {

			requirement,

			best_search_score: bestSearchScore,

			search_status: searchStatus,

			total_matches: workflows.length,

			workflows

		}
	}
];

const workflows = $json.workflows || [];

const prompt = `
You are a Senior AI Workflow Recommendation Expert.

Your task is to analyze the user's business requirement and compare the Top 5 workflows retrieved from the AI Workflow Knowledge Base.

Business Requirement:

${$json.requirement}

Search Status:
${$json.search_status}

Best Search Score:
${$json.best_search_score}

Top 5 Matching Workflows:

${JSON.stringify(workflows, null, 2)}

Instructions:

1. Carefully analyze the user's business requirement.
2. Compare all five workflows.
3. Recommend ONLY ONE best workflow.
4. Explain why it is the best choice.
5. Suggest alternative workflows if applicable.
6. Summarize the comparison.
7. Describe expected business benefits.
8. Estimate ROI.
9. Suggest implementation priority (High, Medium, or Low).
10. If Search Status is "Low Confidence Match", clearly mention that no strong workflow was found in the knowledge base and that the recommendation is based on the closest available matches.
11. Confidence Score Rules:
   - If Best Search Score >= 0.90 → "Very High Confidence"
   - If Best Search Score >= 0.75 → "High Confidence"
   - If Best Search Score >= 0.60 → "Medium Confidence"
   - Otherwise → "Low Confidence"
12. Use the Best Search Score as the Search Score in the response.
13. Return ONLY valid JSON.
14. Do not include markdown, explanations, comments, or code fences.

Return this exact JSON structure:

{
  "recommendation_title": "",
  "business_requirement_analysis": "",
  "recommended_workflow": "",
  "recommendation_reason": "",
  "alternative_workflows": "",
  "comparison_summary": "",
  "business_benefits": "",
  "estimated_roi": "",
  "implementation_priority": "",
  "confidence_score": "",
  "search_score": "",
  "final_recommendation": ""
}
`;

return [
  {
    json: {

      requirement: $json.requirement,

      best_search_score: $json.best_search_score,

      search_status: $json.search_status,

      total_matches: $json.total_matches,

      workflows: workflows,

      payload: {
        contents: [
          {
            parts: [
              {
                text: prompt
              }
            ]
          }
        ]
      }

    }
  }
];

// Get Gemini response
const text = $json.candidates?.[0]?.content?.parts?.[0]?.text;

if (!text) {
	throw new Error("Gemini response not found.");
}

// Clean response
const clean = text
	.replace(/```json/gi, "")
	.replace(/```/g, "")
	.trim();

// Parse JSON
let recommendation;

try {
	recommendation = JSON.parse(clean);
} catch (err) {
	throw new Error("Invalid Gemini JSON:\n\n" + clean);
}

// Get previous node output
const previous = $("Code (Extract Top 5 Workflows)").first().json;

// Return final data
return [
	{
		json: {
			requirement: previous.requirement || "",

			recommended_workflow:
				recommendation.recommended_workflow || "",

			recommendation_title:
				recommendation.recommendation_title || "",

			business_requirement_analysis:
				recommendation.business_requirement_analysis || "",

			recommendation_reason:
				recommendation.recommendation_reason || "",

			alternative_workflows:
				recommendation.alternative_workflows || "",

			comparison_summary:
				recommendation.comparison_summary || "",

			business_benefits:
				recommendation.business_benefits || "",

			estimated_roi:
				recommendation.estimated_roi || "",

			implementation_priority:
				recommendation.implementation_priority || "",

			confidence_score:
				recommendation.confidence_score || "",

			search_score:
				recommendation.search_score || previous.best_search_score,

			final_recommendation:
				recommendation.final_recommendation || "",

			best_search_score:
				previous.best_search_score ?? 0,

			search_status:
				previous.search_status ??
				(
					(previous.best_search_score ?? 0) >= 0.65
						? "High Confidence Match"
						: "Low Confidence Match"
				),

			total_matches:
				previous.total_matches ?? 0,

			created_at:
				new Date().toISOString()
		}
	}
];
